message.content:
{
  "description": "The creature is a large quadrupedal chimera shown in right-facing profile standing on a light ground. It has the head, hooked beak, eye and feathered wings of a raptor joined to the torso, four limbs, paws and long tufted tail of a big cat. The front half including the head, neck, chest and wings is covered in dense overlapping golden-brown to dark brown feathers, while the hindquarters, belly and legs are covered in short tawny-brown fur with a paler underbelly. Two very large wings are raised and spread outward from the upper back. The overall coloration is warm browns, tans and cream with darker brown-black feather edges and a dark tuft at the tip of the tail.",
  "parts": [
    {
      "part": "head",
      "looks_like": "eagle-like head with a large sharply hooked beak that is yellow at the cere and gape and dark gray-black at the hooked tip, a round amber eye with a dark pupil and a pale gray area at the beak base, covered in short golden-brown feathers on the crown, cheeks and throat",
      "where": "at the front of the body at the end of the thick feathered neck, facing to the right"
    },
    {
      "part": "wings",
      "looks_like": "two large outstretched wings with many layers of overlapping flight feathers in mottled golden-brown, tan, cream and dark brown-black, long pointed primaries at the outer edges and shorter coverts toward the body",
      "where": "attached to the upper back just behind the feathered neck, raised upward and spread outward above the torso"
    },
    {
      "part": "legs",
      "looks_like": "four thick muscular legs covered in short tawny-brown fur with lighter cream on the inner and lower portions, with visible joints and musculature",
      "where": "under the body, two forelegs under the chest and two hindlegs under the hips, in a standing walking pose"
    },
    {
      "part": "feet",
      "looks_like": "four large rounded paws with pale fur on the dorsal surface, blunt dark claws and thick padded soles",
      "where": "at the distal ends of each leg in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "long slender fur-covered tail, tawny along its length with a darker brown-black tuft of longer hair at the tip",
      "where": "extending from the rump at the rear of the body, curving down behind the hind legs"
    },
    {
      "part": "feathers",
      "looks_like": "dense overlapping scale-like feathers in shades of golden-brown, chestnut, tan and dark brown with lighter edges, covering the head, neck and chest as a thick ruff and the entire upper surface of the wings",
      "where": "on the head, around the eye and beak, down the dorsal and ventral neck, across the chest and on both wings"
    },
    {
      "part": "mane",
      "looks_like": "shaggy ruff of longer dark brown to blackish hair on the lower chest and between the forelegs, transitioning into the shorter tawny body fur",
      "where": "on the ventral neck, lower chest and front of the torso between the forelegs"
    }
  ],
  "attached_objects": [],
  "animals": [
    "eagle",
    "lion"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 2,
  "extra_limb_pieces": 0,
  "tails": 1
}
